def rule_notice_addressee_operator_name(doc: dict) -> list[dict]:
    """Retrieve the legal operator name from the addressee block at the top of PHMSA notices."""
    try:
        import re

        lines = [s for s in (doc.get("lines") or []) if isinstance(s, dict)]
        if not lines:
            return []

        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def low(text: str) -> str:
            return norm(text).lower()

        def is_blank(text: str) -> bool:
            return not norm(text)

        def is_header_or_notice(text: str) -> bool:
            t = low(text)
            return (
                "notice of probable violation" in t
                or "proposed compliance order" in t
                or "pipeline and hazardous materials safety administration" in t
                or "u.s. department of transportation" in t
                or t.startswith("via electronic mail to:")
            )

        def is_cpf(text: str) -> bool:
            return bool(re.search(r"\bCPF\b", norm(text)))

        def is_email(text: str) -> bool:
            return "@" in text

        def looks_like_person_line(text: str) -> bool:
            t = norm(text)
            if not t:
                return False
            return bool(re.match(r"^(Mr|Ms|Mrs|Dr|Hon)\.?\s+[A-Z]", t))

        def looks_like_title_line(text: str) -> bool:
            t = low(text)
            if not t:
                return False
            title_patterns = [
                r"\bpresident\b",
                r"\bvice president\b",
                r"\bchief executive\b",
                r"\bchief operating\b",
                r"\bchief financial\b",
                r"\bceo\b",
                r"\bcfo\b",
                r"\bcoo\b",
                r"\bdirector\b",
                r"\bmanager\b",
                r"\battorney\b",
                r"\bcounsel\b",
                r"\bsecretary\b",
                r"\bchair\b",
                r"\bchairman\b",
                r"\bgeneral counsel\b",
            ]
            return any(re.search(pat, t) for pat in title_patterns)

        def looks_like_address(text: str) -> bool:
            t = norm(text)
            if not t:
                return False
            low_t = t.lower()
            if re.search(r"\b\d{5}(?:-\d{4})?\b", t) and any(ch.isalpha() for ch in t):
                return True
            if re.search(r"\b(po box|p\.o\. box)\b", low_t):
                return True
            if re.search(
                r"\b(street|st\.|road|rd\.|avenue|ave\.|boulevard|blvd\.|lane|ln\.|drive|dr\.|court|ct\.|place|plaza|suite|ste\.|floor|blg|building|highway|hwy\.)\b",
                low_t,
            ):
                return True
            if re.search(r"\b[A-Z][a-z]+,\s*[A-Z]{2}\s+\d{5}(?:-\d{4})?\b", t):
                return True
            if sum(ch.isdigit() for ch in t) >= 3 and any(
                term in low_t for term in ["street", "road", "avenue", "suite", "drive", "way", "lane", "boulevard"]
            ):
                return True
            return False

        def looks_like_org_name(text: str) -> bool:
            t = norm(text)
            if not t:
                return False
            low_t = t.lower()
            if looks_like_address(t) or looks_like_person_line(t) or looks_like_title_line(t):
                return False
            if is_header_or_notice(t) or is_email(t) or is_cpf(t):
                return False
            if t[0].islower():
                return False
            org_markers = [
                "company",
                "corp",
                "corporation",
                "inc",
                "incorporated",
                "llc",
                "l.l.c",
                "lp",
                "l.p",
                "ltd",
                "limited",
                "pipeline",
                "pipelines",
                "energy",
                "transmission",
                "midstream",
                "terminal",
                "terminals",
                "operating",
                "resources",
                "systems",
                "gas",
                "liquid",
                "liquids",
                "petroleum",
            ]
            if any(marker in low_t for marker in org_markers):
                return True
            if len(t.split()) >= 2 and any(ch.isalpha() for ch in t):
                return True
            return False

        # Find the top address block, then select the first organization-like line
        # after the recipient name/title lines and before the postal address/CPF line.
        cpf_idx = None
        for i, span in enumerate(lines):
            if is_cpf(span.get("text") or ""):
                cpf_idx = i
                break
        if cpf_idx is None:
            cpf_idx = len(lines)

        person_idx = None
        for i, span in enumerate(lines[:cpf_idx]):
            if looks_like_person_line(span.get("text") or ""):
                person_idx = i
                break
        title_idx = None
        for i, span in enumerate(lines[:cpf_idx]):
            if looks_like_title_line(span.get("text") or ""):
                title_idx = i
                break

        anchor_idx = title_idx if title_idx is not None else person_idx
        if anchor_idx is None:
            # Fallback: scan the top block directly for the first organization-like line.
            for span in lines[:cpf_idx]:
                text = span.get("text") or ""
                if looks_like_org_name(text):
                    return [{
                        "text": norm(text),
                        **{k: span[k] for k in ("page_no", "line_no") if k in span},
                    }]
            return []

        candidates = []
        for span in lines[anchor_idx + 1:cpf_idx]:
            text = span.get("text") or ""
            if is_blank(text) or is_header_or_notice(text) or is_email(text):
                continue
            if looks_like_person_line(text) or looks_like_title_line(text):
                continue
            if looks_like_address(text):
                break
            if looks_like_org_name(text):
                candidates.append(span)
                continue

        if candidates:
            best = candidates[0]
            return [{
                "text": norm(best.get("text") or ""),
                **{k: best[k] for k in ("page_no", "line_no") if k in best},
            }]

        return []
    except Exception:
        return []

import re


_MONTHS = (
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
)
_MONTH_RE = "|".join(_MONTHS)

_MONTH_DAY_RE = rf"(?:{_MONTH_RE})\s+\d{{1,2}}(?:,\s*\d{{4}})?"
_DAY_YEAR_RE = r"(?:\d{1,2}(?:,\s*\d{4})?)"
_MONTH_YEAR_RE = rf"(?:{_MONTH_RE})\s+\d{{4}}"
_DATE_RE = rf"(?:{_MONTH_DAY_RE}|\d{{1,2}}/\d{{1,2}}/\d{{2,4}}|\d{{1,2}}-\d{{1,2}}-\d{{2,4}})"

_RANGE_PATTERNS = [
    # The most common opener: "From <date> to/through <date>, ... inspected ..."
    re.compile(
        rf"\bFrom\s+({_DATE_RE})(?:,\s*)?\s+(?:to|through|[-–])\s+({_DATE_RE}|{_DAY_YEAR_RE})",
        re.IGNORECASE,
    ),
    # Openers that describe the inspection as occurring on "various dates between".
    re.compile(
        rf"\bOn\s+various dates between\s+({_MONTH_YEAR_RE}|{_DATE_RE})\s+and\s+({_MONTH_YEAR_RE}|{_DATE_RE})",
        re.IGNORECASE,
    ),
    # Openers like "Between July and October 2021, a representative ... inspected ...".
    re.compile(
        rf"\bBetween\s+({_MONTH_RE})\s+and\s+({_MONTH_RE})\s+\d{{4}}",
        re.IGNORECASE,
    ),
    # Openers like "From/For the weeks of July 29 to August 2, 2024, and ...".
    re.compile(
        r"\b(?:From|For)\s+the\s+weeks?\s+of\s+(.+?)(?=,\s*(?:a|an|the|one|representative|representatives|PHMSA)\b|\s+(?:a|an|the|one|representative|representatives|PHMSA)\b)",
        re.IGNORECASE,
    ),
    # Openers like "During the September 20 through 24, 2021 field inspection".
    re.compile(
        rf"\bDuring\s+the\s+((?:{_MONTH_RE})\s+\d{{1,2}}\s+(?:to|through|[-–])\s+(?:(?:{_MONTH_RE})\s+)?\d{{1,2}}(?:,\s*\d{{4}})?)\s+(?:field\s+)?inspection\b",
        re.IGNORECASE,
    ),
    # Openers like "During PHMSA's field inspection on April 10, 2025".
    re.compile(
        rf"\bDuring\s+(?:PHMSA(?:'s)?\s+)?(?:on-site\s+)?(?:field\s+)?inspection\s+on\s+({_DATE_RE})",
        re.IGNORECASE,
    ),
    # Single-date openers: "On May 10, 2023, ... inspected ..."
    re.compile(
        rf"\bOn\s+({_DATE_RE})",
        re.IGNORECASE,
    ),
]

_FALLBACK_OPENING_RE = re.compile(
    r"^\s*(?:From|On|During)\b.{0,260}?\binspect(?:ed|ion)\b",
    re.IGNORECASE | re.DOTALL,
)


def rule_phmsa_inspection_date_range(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def make_span(text: str, src: dict | None = None) -> dict:
            span = {"text": norm(text)}
            if src:
                for key in ("page_no", "line_no", "paragraph_no"):
                    if key in src:
                        span[key] = src[key]
            return span

        def maybe_add_span(text: str, src: dict | None = None) -> list[dict] | None:
            text = norm(text)
            if not text:
                return None

            for pat in _RANGE_PATTERNS:
                match = pat.search(text)
                if not match:
                    continue
                if pat is _RANGE_PATTERNS[2]:
                    return [make_span(match.group(0), src)]
                if pat is _RANGE_PATTERNS[3]:
                    return [make_span(match.group(1), src)]
                if pat is _RANGE_PATTERNS[4]:
                    return [make_span(match.group(1), src)]
                if pat is _RANGE_PATTERNS[5]:
                    return [make_span(match.group(1), src)]
                # Preserve the full matched range phrase for the other opener types.
                return [make_span(match.group(0), src)]

            fallback = _FALLBACK_OPENING_RE.search(text)
            if fallback and re.search(r"\b(?:PHMSA|representative|representatives|inspector)\b", fallback.group(0), re.IGNORECASE):
                return [make_span(fallback.group(0), src)]
            return None

        # Search the most local/topical containers first.
        for source_key, limit in (("pages", 2), ("paragraphs", 12), ("lines", 40)):
            items = [s for s in (doc.get(source_key) or []) if isinstance(s, dict)]
            for item in items[:limit]:
                found = maybe_add_span(item.get("text") or "", item)
                if found:
                    return found

        # Fallback to the top of the raw text if the document was split unusually.
        text = doc.get("text") or ""
        head = text[:4000] if isinstance(text, str) else ""
        found = maybe_add_span(head, None)
        if found:
            return found

        return []
    except Exception:
        return []

import re


_COLON_RE = re.compile(
    r"^\s*CPF\s*:\s*([1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*-\s*NOPV)\s*$",
    re.IGNORECASE,
)
_STANDARD_RE = re.compile(
    r"^\s*CPF\s+([1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*(?:-\s*|\s+)NOPV)\s*$",
    re.IGNORECASE,
)
_TEXT_RE = re.compile(
    r"(?:^|\n)\s*CPF\s*:\s*([1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*-\s*NOPV)\s*(?:$|\n)|"
    r"(?:^|\n)\s*(CPF\s+[1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*(?:-\s*|\s+)NOPV)\s*(?:$|\n)",
    re.IGNORECASE,
)
_ANYWHERE_RE = re.compile(
    r"CPF\s*:\s*([1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*-\s*NOPV)|"
    r"\b(CPF\s+[1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*(?:-\s*|\s+)NOPV)\b",
    re.IGNORECASE,
)


def rule_cpf_case_number(doc: dict) -> list[dict]:
    try:
        for source_key in ("lines", "paragraphs"):
            for item in doc.get(source_key) or []:
                text = (item.get("text") or "").strip()
                if not text:
                    continue

                colon_match = _COLON_RE.match(text)
                if colon_match:
                    span = {"text": colon_match.group(1).strip()}
                    if "page_no" in item:
                        span["page_no"] = item["page_no"]
                    if "line_no" in item:
                        span["line_no"] = item["line_no"]
                    if "paragraph_no" in item:
                        span["paragraph_no"] = item["paragraph_no"]
                    return [span]

                standard_match = _STANDARD_RE.match(text)
                if standard_match:
                    span = {
                        "text": f"The CPF case number assigned to this enforcement action is {text}"
                    }
                    if "page_no" in item:
                        span["page_no"] = item["page_no"]
                    if "line_no" in item:
                        span["line_no"] = item["line_no"]
                    if "paragraph_no" in item:
                        span["paragraph_no"] = item["paragraph_no"]
                    return [span]

        full_text = (doc.get("text") or "").strip()
        if full_text:
            text_match = _TEXT_RE.search(full_text)
            if text_match:
                text = text_match.group(1) or text_match.group(2)
                if text:
                    if text_match.group(1):
                        return [{"text": text.strip()}]
                    return [
                        {
                            "text": f"The CPF case number assigned to this enforcement action is {text.strip()}",
                        }
                    ]

            anywhere_match = _ANYWHERE_RE.search(full_text)
            if anywhere_match:
                text = anywhere_match.group(1) or anywhere_match.group(2)
                if text:
                    if anywhere_match.group(1):
                        return [{"text": text.strip()}]
                    return [
                        {
                            "text": f"The CPF case number assigned to this enforcement action is {text.strip()}",
                        }
                    ]

        return []
    except Exception:
        return []

import re


def rule_operator_regulated_part(doc: dict) -> list[dict]:
    try:
        parts_re = re.compile(r"\b(?:49\s*C\.?\s*F\.?\s*R\.?\s*)?(?:Part|part)\s*(192|193|195|199)\b", re.I)
        anchor_re = re.compile(
            r"(subject to|covered by|requirements? of|compliance with|in accordance with|conforms? to|"
            r"required by this part|should have been subject|not subject to|codified in|regulated by)",
            re.I,
        )

        def iter_items():
            for key in ("paragraphs", "lines", "pages"):
                for item in doc.get(key, []) or []:
                    text = (item.get("text") or "").strip()
                    if text:
                        yield key, item, text

        best_candidate = None

        for source, item, text in iter_items():
            if not anchor_re.search(text):
                continue
            for match in parts_re.finditer(text):
                lowered = text.lower()
                specificity = 0
                for phrase in (
                    "subject to",
                    "covered by",
                    "requirements of",
                    "compliance with",
                    "in accordance with",
                    "conforms to",
                    "required by this part",
                    "should have been subject",
                    "not subject to",
                    "codified in",
                    "regulated by",
                ):
                    if phrase in lowered:
                        specificity += 1
                if source == "lines":
                    source_rank = 0
                elif source == "paragraphs":
                    source_rank = 1
                else:
                    source_rank = 2
                word_count = max(1, len(text.split()))

                span = {"text": text}
                for field in ("page_no", "paragraph_no", "line_no"):
                    if field in item:
                        span[field] = item[field]
                span["_source"] = source
                candidate = (word_count, -specificity, source_rank, span.get("page_no", 0), span.get("paragraph_no", 0), span.get("line_no", 0), span)
                if best_candidate is None or candidate < best_candidate:
                    best_candidate = candidate

        if best_candidate is None:
            # Fallback: capture the first nearby sentence-like snippet with a Part citation.
            full_text = doc.get("text") or ""
            for match in parts_re.finditer(full_text):
                start = max(0, match.start() - 140)
                end = min(len(full_text), match.end() + 180)
                snippet = full_text[start:end].strip()
                if anchor_re.search(snippet):
                    return [{"text": snippet}]
            return []

        span = best_candidate[-1]
        span.pop("_source", None)
        return [span]
    except Exception:
        return []

